pub fn dump_tables(
    out: &mut impl Write,
    path: &str,
    font: &read_fonts::FontRef<'_>,
) -> io::Result<()> {
    use read_fonts::FontRead;
    {
        crate::dump_support::begin_table();
        let path = &format!("{path}.kerx");
        let tag = Tag::new(b"kerx");
        match font
            .table_data(tag)
            .ok_or(ReadError::TableIsMissing(tag))
            .and_then(Kerx::read)
        {
            Ok(table) => dump_Kerx(out, path, &table)?,
            Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
        }
    }
    Ok(())
}
